function WassersteinPermOptimum(d):
    n <- number of rows of d
    best_cost <- +infinity
    best_sigma <- (0,1,...,n-1)
    for each permutation sigma of {0,...,n-1}:
        cost <- (1/n) * sum over i of d[i][sigma[i]]
        if cost < best_cost:
            best_cost <- cost
            best_sigma <- sigma
    return (best_cost, best_sigma)

